import{_ as t,H as e,f as _,i as a}from"./chunks/framework.BH2BK_3i.js";const f=JSON.parse('{"title":"旅程再启｜培养你的数据分析思维","description":"","frontmatter":{},"headers":[],"relativePath":"数据分析实战45讲/旅程再启｜培养你的数据分析思维.md","filePath":"数据分析实战45讲/旅程再启｜培养你的数据分析思维.md","lastUpdated":1779820717000}'),i={name:"数据分析实战45讲/旅程再启｜培养你的数据分析思维.md"};function l(r,p,o,n,s,d){return e(),_("div",null,[...p[0]||(p[0]=[a('<h1 id="旅程再启-培养你的数据分析思维" tabindex="-1">旅程再启｜培养你的数据分析思维 <a class="header-anchor" href="#旅程再启-培养你的数据分析思维" aria-label="Permalink to &quot;旅程再启｜培养你的数据分析思维&quot;">​</a></h1><p>你好，我是陈博士，好久不见！</p><p>在专栏结束了五年多以后，我决定对专栏进行一次迭代，分享一些新的积累。</p><p>在这段时间里，基于我自身的工作需要和线下培训项目的沉淀，我对数据分析有了一些新的认识。加上在专栏的第四模块——数据分析工作篇中，我们仅用了一节课来认识了数据分析思维的重要性，分享了一些非常简单的培养方法，并没有具体的方法论支持，所以我觉得有必要针对这部分进行一些扩展，分享一些较为通用的经典的行业方法论，结合具体场景，真正帮助到你的工作。</p><p>我曾在开篇词中说过：我们生活在数据驱动一切的时代，数据挖掘和数据分析就是这个时代的“淘金”。这句话的含金量还在上升。如今的大模型，也是诞生于庞大的数据之上。数据分析思维的重要性，在当下及未来，不言而喻。</p><p><strong>目前拟定增加的话题如下：</strong></p><ol><li><p>BCG分类：采购人员如何与供应商谈降本？</p></li><li><p>RFM分层：店铺收入大幅下跌的原因是什么？</p></li><li><p>AARRR模型：如何找到运营中的薄弱环节并进行优化？</p></li><li><p>AIPL模型：可口可乐的品牌资产是多少？</p></li><li><p>人生阶段：针对用户的不同人生阶段推荐哪些产品？</p></li><li><p>客户生命周期管理：你的产品客户结构是怎样的？</p></li><li><p>不同场景下的数据分析思维</p></li></ol><p>如果你有更多想要了解的内容，也欢迎在留言区写下你的问题，我们共同探讨！加更的部分，每周三和周五0点更新，敬请期待。</p><p><strong>另外，针对以上的数据分析思维，我还会做一个 AI Agent 工具，帮你进行针对性的方案设计。</strong> 你只需要将你的业务场景进行描述，然后 AI Agent 就会分别调用这些分析模型进行思考，撰写对应的实施方案。预计本周内上线。</p>',9)])])}const m=t(i,[["render",l]]);export{f as __pageData,m as default};
